function applyTheme(){const saved=localStorage.getItem('ledger-theme');const dark=saved?saved==='dark':matchMedia('(prefers-color-scheme: dark)').matches;document.documentElement.dataset.theme=dark?'dark':'light';document.querySelector('meta[name="theme-color"]')?.setAttribute('content',dark?'#111214':'#f5f5f7');const b=$('#theme-toggle');if(b){b.textContent=dark?'☀':'☾';b.title=dark?'Switch to light mode':'Switch to dark mode';b.setAttribute('aria-label',b.title)}}
