async function loadApp(){let financeLoaded=true;try{finance=await api('/api/finance')}catch{financeLoaded=false;finance={accounts:[],cards:[],cardPayments:[],purchases:[],subscriptions:[],goals:[],debts:[],investments:[],retirement:[],retirementSettings:{annualRate:10,years:30}}};const me=await api('/api/me');email=me.email;$('#admin-nav').classList.toggle('hidden',!me.is_admin);['accounts','cards','cardPayments','purchases','subscriptions','goals','debts','investments','retirement','netWorthHistory'].forEach(k=>finance[k]??=[]);finance.retirementSettings??={annualRate:10,years:30};finance.retirementSettings.annualRate??=10;finance.retirementSettings.years??=30;finance.cards.forEach(c=>c.id??=crypto.randomUUID());finance.subscriptions.forEach(s=>{s.id??=crypto.randomUUID();s.cadence=subscriptionIsYearly(s)?'Yearly':'Monthly'});finance.debts.forEach(d=>{d.id??=crypto.randomUUID();d.history??=[]});finance.investments.forEach(i=>i.id??=crypto.randomUUID());finance.retirement.forEach(r=>r.id??=crypto.randomUUID());const snapshotAdded=recordNetWorthSnapshot();$('#auth').classList.add('hidden');$('#app').classList.remove('hidden');$('#user-email').textContent=email;$('#avatar').textContent=(email[0]||'Y').toUpperCase();$('#today-label').textContent=new Intl.DateTimeFormat('en-US',{weekday:'long',month:'long',day:'numeric'}).format(new Date()).toUpperCase();applyTheme();render('Overview');if(snapshotAdded&&financeLoaded)try{await api('/api/finance',{data:finance})}catch{}if(!me.has_recovery){const recovery=await api('/api/recovery/rotate',{});await showRecoveryCode(recovery.recovery_code,'Save your recovery code') }}
