document.addEventListener('keydown',e=>{if(e.key==='Escape'&&appShell.classList.contains('sidebar-open'))$('#sidebar-scrim').click()});
function totalBalance(){const latest={};finance.accounts.forEach(a=>{const key=(a.name||'').trim().toLowerCase();if(!latest[key]||a.date>latest[key].date)latest[key]=a});return Object.values(latest).reduce((s,a)=>s+Number(a.amount||0),0)}
function accountBalanceAt(month){const cutoff=`${month}-31`,latest={};finance.accounts.filter(a=>a.date&&a.date<=cutoff).forEach(a=>{const key=(a.name||'').trim().toLowerCase();if(!latest[key]||a.date>latest[key].date)latest[key]=a});return Object.values(latest).reduce((sum,a)=>sum+Number(a.amount||0),0)}
function accountMonthChange(){const previous=monthKey(1);return finance.accounts.some(a=>(a.date||'').slice(0,7)===previous)?accountBalanceAt(monthKey())-accountBalanceAt(previous):null}
function netWorthTotal(){return totalBalance()+totalInvestments()+totalRetirement()-totalDebt()-finance.cards.reduce((sum,c)=>sum+Number(c.balance||0),0)}
function recordNetWorthSnapshot(){const month=new Date().toISOString().slice(0,7),value=netWorthTotal(),existing=finance.netWorthHistory.find(snapshot=>snapshot.month===month);if(existing){if(Number(existing.value)===value)return false;existing.value=value;existing.updatedAt=new Date().toISOString();return true}finance.netWorthHistory.push({month,value,updatedAt:new Date().toISOString()});finance.netWorthHistory.sort((a,b)=>a.month.localeCompare(b.month));return true}
function monthKey(offset=0){const d=new Date();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()-offset);return d.toISOString().slice(0,7)}
function monthSpendToDate(offset=0){const now=new Date(),d=new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth()-offset,1)),month=d.toISOString().slice(0,7),lastDay=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate(),day=offset===0?now.getUTCDate():Math.min(now.getUTCDate(),lastDay),cutoff=`${month}-${String(day).padStart(2,'0')}`;return finance.purchases.filter(p=>(p.date||'').slice(0,7)===month&&(p.date||'')<=cutoff).reduce((sum,p)=>sum+Number(p.amount||0),0)}
function monthSpend(){return monthSpendToDate(0)}
function totalDebt(){return finance.debts.reduce((s,d)=>s+Number(d.balance||0),0)}
function debtPaydownSinceTracking(){const tracked=finance.debts.filter(d=>d.history?.length>1);if(!tracked.length)return null;return tracked.reduce((sum,d)=>{const first=[...d.history].sort((a,b)=>(a.date||'').localeCompare(b.date||''))[0];return sum+Number(first.balance||0)-Number(d.balance||0)},0)}
function totalCardBalance(){return finance.cards.reduce((s,c)=>s+Number(c.balance||0),0)}
function totalLiabilities(){return totalDebt()+totalCardBalance()}
function totalAssets(){return totalBalance()+totalInvestments()+totalRetirement()}
function netWorthChange(){const previous=finance.netWorthHistory.filter(s=>s.month<monthKey()).sort((a,b)=>a.month.localeCompare(b.month)).at(-1);return previous?{amount:netWorthTotal()-Number(previous.value||0),month:previous.month}:null}
function monthCaption(month){return new Date(`${month}-01T12:00:00Z`).toLocaleDateString('en-US',{month:'short',year:'numeric',timeZone:'UTC'})}
function monthlyDebtPayments(){return finance.debts.reduce((s,d)=>s+Number(d.payment||0),0)}
function subscriptionIsYearly(s){return /year|annual/i.test(s.cadence||'')}
function subscriptionMonthlyCost(s){return Number(s.amount||0)/(subscriptionIsYearly(s)?12:1)}
function investmentValue(i){return Number(i.units||0)*Number(i.price||0)}
function investmentBasisValue(i){return i.costBasis===null||i.costBasis===undefined||i.costBasis===''?null:Number(i.units||0)*Number(i.costBasis)}
function investmentsWithCostBasis(){return finance.investments.filter(i=>investmentBasisValue(i)!==null).length}
function investmentBasisTotal(){return finance.investments.reduce((s,i)=>s+(investmentBasisValue(i)??0),0)}
function investmentProfit(){return finance.investments.reduce((s,i)=>{const basis=investmentBasisValue(i);return s+(basis===null?0:investmentValue(i)-basis)},0)}
function investmentProfitPercent(){const basis=investmentBasisTotal();return basis>0?investmentProfit()/basis*100:null}
function totalInvestments(){return finance.investments.reduce((s,i)=>s+investmentValue(i),0)}
function totalRetirement(){return finance.retirement.reduce((s,r)=>s+Number(r.balance||0),0)}
function monthlyRetirementContributions(){return finance.retirement.reduce((s,r)=>s+Number(r.monthlyContribution||0),0)}
function investmentCategories(){return finance.investments.reduce((g,i)=>{const category=i.category||'Other';g[category]=(g[category]||0)+investmentValue(i);return g},{})}
function investmentSummary(){const groups=Object.entries(investmentCategories()).sort((a,b)=>b[1]-a[1]);const max=Math.max(1,...groups.map(([,v])=>v));const profit=investmentProfit(),pct=investmentProfitPercent();return `<section class="panel"><div class="panel-heading"><div><span class="eyebrow">MANUAL PORTFOLIO</span><h2>Investments</h2></div><button class="select-small" data-goto="Investments">View portfolio →</button></div><div class="spend-total" style="margin-top:12px">${moneyExact(totalInvestments())}</div><div class="spend-caption">Current value across ${finance.investments.length} holdings</div><div class="portfolio-profit ${profit>=0?'profit-up':'profit-down'}">Unrealized P/L <strong>${investmentsWithCostBasis()>0?`${profit>=0?'+':''}${moneyExact(profit)}${pct===null?'':` (${pct.toFixed(1)}%)`}`:'Add cost basis to see P/L'}</strong></div><div class="category-list">${groups.length?groups.slice(0,4).map(([category,value])=>`<div class="category-row"><span>${escapeHtml(category)}</span><div class="category-bar"><span style="width:${Math.round(value/max*100)}%"></span></div><b>${moneyExact(value)}</b></div>`).join(''):'<div class="empty">Add holdings to see your portfolio mix.</div>'}</div></section>`}
function retirementSummary(){return `<section class="panel"><div class="panel-heading"><div><span class="eyebrow">RETIREMENT</span><h2>Long-term savings</h2></div><button class="select-small" data-goto="Retirement">View projection →</button></div><div class="spend-total" style="margin-top:12px">${moneyExact(totalRetirement())}</div><div class="spend-caption">${moneyExact(monthlyRetirementContributions())} contributed monthly across ${finance.retirement.length} accounts</div></section>`}
function escapeHtml(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function categoryColor(category){const colors={'food & dining':'#e59b55','transport':'#648fd0','shopping':'#9a7bd1','home':'#c97786','health':'#54a995','entertainment':'#d5ad4e','utilities':'#5da8b8','other':'#8d9a91'},key=String(category||'Other').toLowerCase();if(colors[key])return colors[key];let hash=0;for(const char of key)hash=(hash*31+char.charCodeAt(0))|0;return ['#e59b55','#648fd0','#9a7bd1','#c97786','#54a995','#d5ad4e','#5da8b8','#8d9a91'][Math.abs(hash)%8]}
function render(page){$('#page-title').textContent=page==='Admin'?'User administration':page==='Security'?'Security & recovery':page;$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#add-transaction').classList.toggle('hidden',page!=='Overview'&&page!=='Transactions');$('#page-content').innerHTML=page==='Overview'?overview():page==='Transactions'?transactions():page==='Accounts'?accountsPage():page==='Cards'?cardsPage():page==='Investments'?investmentsPage():page==='Retirement'?retirementPage():page==='Debts'?debtsPage():page==='Admin'?adminPage():page==='Security'?securityPage():page==='Subscriptions'?subsPage():goalsPage();appShell.classList.remove('sidebar-open');mobileMenuToggle.setAttribute('aria-expanded','false');mobileMenuToggle.setAttribute('aria-label','Open navigation');bindPage()}
function overview(){const spend=monthSpend(),lastMonthSpend=monthSpendToDate(1),net=netWorthTotal(),netDelta=netWorthChange(),month=today().slice(0,7),monthlyPurchases=finance.purchases.filter(p=>(p.date||'').slice(0,7)===month&&(p.date||'')<=today()),activeSubscriptions=finance.subscriptions.filter(s=>s.active!==false),monthlySubscriptions=activeSubscriptions.reduce((n,s)=>n+Number(s.amount||0)*(s.cadence==='Yearly'?1/12:1),0);const spendDelta=spend-lastMonthSpend;const spendTrend=lastMonthSpend===0?'No spending in the same period last month':spendDelta===0?'Even with the same period last month':`${spendDelta>0?'↑':'↓'} ${Math.abs(spendDelta/lastMonthSpend*100).toFixed(0)}% vs same period last month`;const recent=[...finance.purchases].sort((a,b)=>(b.date||'').localeCompare(a.date||'')).slice(0,5);const categories={};monthlyPurchases.forEach(p=>{const category=p.category||'Other';categories[category]=(categories[category]||0)+Number(p.amount)});const cat=Object.entries(categories).sort((a,b)=>b[1]-a[1]);return `<div class="cards-grid"><div class="metric-card"><div class="metric-head">Net worth <span class="metric-icon">◌</span></div><div class="metric-value">${money(net)}</div><div class="metric-caption">${money(totalAssets())} assets · ${money(totalLiabilities())} liabilities</div>${netDelta!==null?`<div class="metric-trend ${netDelta.amount>=0?'trend-up':'trend-down'}">${netDelta.amount>=0?'↑':'↓'} ${money(Math.abs(netDelta.amount))} vs ${monthCaption(netDelta.month)}</div>`:''}</div><div class="metric-card"><div class="metric-head">Spent this month <span class="metric-icon">↘</span></div><div class="metric-value">${money(spend)}</div><div class="metric-caption">${monthlyPurchases.length} purchases · month to date</div><div class="metric-trend ${spendDelta<=0?'trend-up':'trend-down'}">${spendTrend}</div></div><div class="metric-card"><div class="metric-head">Total liabilities <span class="metric-icon">⌁</span></div><div class="metric-value">${money(totalLiabilities())}</div><div class="metric-caption">${money(totalDebt())} loans · ${money(totalCardBalance())} cards</div><div class="metric-trend trend-neutral">${money(monthlyDebtPayments())} expected loan payments / month</div></div><div class="metric-card"><div class="metric-head">Monthly subscriptions <span class="metric-icon">⟳</span></div><div class="metric-value">${money(monthlySubscriptions)}</div><div class="metric-caption">${activeSubscriptions.length} active recurring costs</div><div class="metric-trend trend-neutral">${money(monthlySubscriptions*12)} estimated yearly total</div></div></div>
<div class="dashboard-grid"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">YOUR MOMENTUM</span><h2>Spending over time</h2></div><select class="select-small" id="chart-range"><option value="6">Last 6 months</option><option value="3">Last 3 months</option><option value="12">Last 12 months</option></select></div><div class="chart-wrap">${chart()}</div><div class="chart-labels">${monthLabels()}</div></section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">THIS MONTH</span><h2>Where it’s going</h2></div><div class="spend-total">${money(spend)}</div></div><div class="spend-caption">Purchase categories · color matches the chart</div><div class="category-list">${cat.length?cat.map(([k,v])=>`<div class="category-row"><span class="category-name"><i style="--category-color:${categoryColor(k)}"></i>${escapeHtml(k)}</span><div class="category-bar"><span style="width:${Math.round(v/spend*100)}%;--category-color:${categoryColor(k)}"></span></div><b>${money(v)}</b></div>`).join(''):'<div class="empty">Log purchases to see your spending mix.</div>'}</div></section></div>
<div class="lower-grid"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">LATEST ACTIVITY</span><h2>Recent purchases</h2></div><button class="select-small" data-goto="Transactions">View all →</button></div>${purchaseTable(recent)}</section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">KEEP MOVING</span><h2>Your goals</h2></div><button class="select-small" data-goto="Goals">Manage →</button></div>${goalsList()}</section>${investmentSummary()}${retirementSummary()}</div>`}
function chart(range=6){
  const months=[],data=[],categories=new Set();
  for(let i=range-1;i>=0;i--){const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-i);const month=d.toISOString().slice(0,7),label=d.toLocaleString('en-US',{month:'short'}),purchases=finance.purchases.filter(p=>(p.date||'').slice(0,7)===month&&(month!==today().slice(0,7)||(p.date||'')<=today())),totals={};purchases.forEach(p=>{const category=p.category||'Other';totals[category]=(totals[category]||0)+Number(p.amount||0);categories.add(category)});months.push(label);data.push(totals)}
  const names=[...categories],totals=data.map(month=>Object.values(month).reduce((sum,value)=>sum+value,0)),max=Math.max(100,...totals)*1.12,ticks=[max,max/2,0],axis=value=>value>=1000?`$${(value/1000).toFixed(value>=10000?0:1).replace('.0','')}k`:`$${Math.round(value)}`;
  return `<div class="bar-chart" style="--chart-count:${range}" role="img" aria-label="Monthly spending by category"><div class="bar-chart-axis">${ticks.map(tick=>`<span>${axis(tick)}</span>`).join('')}</div><div class="bar-chart-plot">${ticks.map((_,i)=>`<i class="bar-chart-guide" style="top:${i*50}%"></i>`).join('')}<div class="bar-chart-columns">${data.map((month,i)=>{const total=totals[i];return `<div class="bar-chart-column"><div class="spending-stack ${i===data.length-1?'current':''}" style="height:${Math.max(total?1:0,total/max*100)}%;--bar-index:${i}" title="${months[i]}: ${moneyExact(total)}">${names.filter(name=>month[name]>0).map(name=>`<span style="height:${month[name]/total*100}%;--category-color:${categoryColor(name)}" title="${escapeHtml(name)}: ${moneyExact(month[name])}"></span>`).join('')}</div></div>`}).join('')}</div></div></div>`
}
function monthLabels(range=6){return Array.from({length:range},(_,i)=>{let d=new Date();d.setDate(1);d.setMonth(d.getMonth()-range+1+i);return d.toLocaleString('en-US',{month:'short'})}).map(x=>`<span>${x}</span>`).join('')}
function purchaseTable(rows){if(!rows.length)return '<div class="empty">No purchases yet. Start by logging one.</div>';return `<table class="table"><thead><tr><th>MERCHANT</th><th>CATEGORY</th><th>DATE</th><th class="amount">AMOUNT</th></tr></thead><tbody>${rows.map(p=>`<tr><td><div class="merchant-cell"><span class="merchant-icon">${escapeHtml((p.merchant||'?')[0].toUpperCase())}</span>${escapeHtml(p.merchant)}</div></td><td><span class="category-tag">${escapeHtml(p.category)}</span></td><td>${escapeHtml(p.date)}</td><td class="amount">−${money(p.amount)}</td></tr>`).join('')}</tbody></table>`}
function goalsList(){const goals=finance.goals.slice(0,3);return goals.length?goals.map(g=>{const pct=Math.min(100,Math.round(Number(g.saved||0)/Math.max(1,Number(g.target||1))*100));return `<div class="goal-row"><div class="goal-top"><strong>${escapeHtml(g.name)}</strong><span>${money(g.saved)} / ${money(g.target)}</span></div><div class="goal-track"><span style="width:${pct}%"></span></div><div class="goal-meta"><span>${pct}% there</span><span>${g.date?`Target ${escapeHtml(g.date)}`:'Keep it up'}</span></div></div>`}).join(''):'<div class="empty">Set a goal and make a little progress each month.</div>'}
function transactions(){const count=finance.purchases.length,total=finance.purchases.reduce((sum,p)=>sum+Number(p.amount||0),0),average=count?total/count:0;return `<div class="cards-grid metric-trio"><div class="metric-card"><div class="metric-head">Total logged purchases <span class="metric-icon">↕</span></div><div class="metric-value">${count}</div><div class="metric-caption">Across all recorded dates</div></div><div class="metric-card"><div class="metric-head">Total logged spend <span class="metric-icon">−</span></div><div class="metric-value">${money(total)}</div><div class="metric-caption">Sum of recorded purchases</div></div><div class="metric-card"><div class="metric-head">Average purchase <span class="metric-icon">∅</span></div><div class="metric-value">${money(average)}</div><div class="metric-caption">Across ${count} transactions</div></div></div><section class="panel" style="margin-top:16px"><div class="panel-heading"><div><span class="eyebrow">PURCHASE HISTORY</span><h2>Find a transaction</h2></div><div class="form-row"><input id="search" class="select-small" placeholder="Search merchant…" aria-label="Search merchant"><select id="filter-category" class="select-small" aria-label="Filter category"><option value="">All categories</option>${[...new Set(finance.purchases.map(p=>p.category))].map(c=>`<option>${escapeHtml(c)}</option>`).join('')}</select><input id="filter-month" class="select-small" type="month" aria-label="Filter by month"></div></div><div id="purchase-results">${purchaseTable([...finance.purchases].sort((a,b)=>(b.date||'').localeCompare(a.date||'')))}</div></section>`}
function accountsPage(){const change=accountMonthChange(),accountCount=new Set(finance.accounts.map(a=>(a.name||'').trim().toLowerCase())).size;return `<div class="cards-grid metric-trio"><div class="metric-card"><div class="metric-head">Current bank balances <span class="metric-icon">▤</span></div><div class="metric-value">${money(totalBalance())}</div><div class="metric-caption">Latest snapshot for each account</div></div><div class="metric-card"><div class="metric-head">Monthly change <span class="metric-icon">↗</span></div><div class="metric-value ${change===null?'':change>=0?'profit-up':'profit-down'}">${change===null?'—':`${change>=0?'+':''}${money(change)}`}</div><div class="metric-caption">${change===null?'Add last month’s snapshot to compare':'Compared with last month'}</div></div><div class="metric-card"><div class="metric-head">Tracked accounts <span class="metric-icon">◎</span></div><div class="metric-value">${accountCount}</div><div class="metric-caption">${finance.accounts.length} monthly snapshots saved</div></div></div><div class="panel-heading" style="margin-top:25px"><div><span class="eyebrow">BALANCES OVER TIME</span><h2>Account snapshots</h2></div><button id="add-account" class="primary">＋ Add balance</button></div><p class="debt-note">Save one snapshot for each account each month. If you enter the same account and month again, it updates that month’s snapshot instead of creating a duplicate.</p><div class="subpage-grid">${finance.accounts.length?finance.accounts.map(a=>`<div class="content-card"><span class="eyebrow">${escapeHtml(a.date)}</span><h3 style="margin-top:8px">${escapeHtml(a.name)}</h3><div class="metric-value">${money(a.amount)}</div></div>`).join(''):'<div class="content-card"><h3>Track your starting point</h3><p>Add a current balance. Log another snapshot next month to see how your savings grow.</p></div>'}</div>`}
function investmentsPage(){
  const groups=Object.entries(investmentCategories()).sort((a,b)=>b[1]-a[1]),max=Math.max(1,...Object.values(investmentCategories()));
  const profit=investmentProfit(),basisTotal=investmentBasisTotal(),profitPercent=investmentProfitPercent();
  return `<div class="cards-grid metric-trio"><div class="metric-card"><div class="metric-head">Total investment value <span class="metric-icon">◒</span></div><div class="metric-value">${moneyExact(totalInvestments())}</div><div class="metric-caption">${finance.investments.length} manually tracked holdings</div></div><div class="metric-card"><div class="metric-head">Unrealized P/L <span class="metric-icon">↗</span></div><div class="metric-value ${profit>=0?'profit-up':'profit-down'}">${investmentsWithCostBasis()>0?`${profit>=0?'+':''}${moneyExact(profit)}`:'—'}</div><div class="metric-caption">${profitPercent===null?'Enter cost basis to track P/L':`${profitPercent.toFixed(1)}% return`}</div></div><div class="metric-card"><div class="metric-head">Asset categories <span class="metric-icon">▥</span></div><div class="metric-value">${groups.length}</div><div class="metric-caption">Stocks, crypto, CDs, and more</div></div></div><div class="panel-heading" style="margin-top:25px"><div><span class="eyebrow">YOUR PORTFOLIO</span><h2>Investments</h2></div><button id="add-investment" class="primary">＋ Add holding</button></div><p class="debt-note">Enter prices and cost basis yourself; Ledgerly does not fetch quotes. Value is units × current price. P/L is current value minus cost basis for holdings where you entered one. For a CD, use 1 unit and enter its current value as the price.</p><div class="dashboard-grid invest-layout"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">ALLOCATION</span><h2>Value by category</h2></div></div><div class="category-list">${groups.length?groups.map(([category,value])=>`<div class="category-row"><span>${escapeHtml(category)}</span><div class="category-bar"><span style="width:${Math.round(value/max*100)}%"></span></div><b>${moneyExact(value)}</b></div>`).join(''):'<div class="empty">Your categories will appear here.</div>'}</div></section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">CURRENT VALUE</span><h2>Holdings</h2></div></div>${finance.investments.length?`<table class="table investment-table"><thead><tr><th>ASSET</th><th>CATEGORY</th><th>UNITS</th><th>COST BASIS</th><th>PRICE</th><th class="amount">VALUE</th><th class="amount">P/L</th></tr></thead><tbody>${finance.investments.map(i=>`<tr><td><div class="merchant-cell"><span class="merchant-icon">${escapeHtml((i.ticker||i.name||'?')[0].toUpperCase())}</span><span>${escapeHtml(i.name)}${i.ticker?`<small class="holding-ticker">${escapeHtml(i.ticker)}</small>`:''}</span></div><button class="price-update" data-update-investment="${escapeHtml(i.id)}">Update holding</button><small class="holding-ticker">Updated ${escapeHtml(i.updatedAt||'—')}</small></td><td><span class="category-tag">${escapeHtml(i.category||'Other')}</span></td><td>${Number(i.units||0).toLocaleString('en-US',{maximumFractionDigits:6})}</td><td>${investmentBasisValue(i)===null?'—':moneyUnit(i.costBasis)}</td><td>${moneyUnit(i.price)}</td><td class="amount">${moneyExact(investmentValue(i))}</td><td class="amount ${investmentBasisValue(i)===null?'profit-na':investmentValue(i)>=investmentBasisValue(i)?'profit-up':'profit-down'}">${investmentBasisValue(i)===null?'—':`${investmentValue(i)>=investmentBasisValue(i)?'+':''}${moneyExact(investmentValue(i)-investmentBasisValue(i))}`}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Add a holding to start your portfolio.</div>'}</section></div>`
}
function cardsPage(){const month=today().slice(0,7),cardPurchases=finance.purchases.filter(p=>p.card&&(p.date||'').slice(0,7)===month&&(p.date||'')<=today()),payments=finance.cardPayments.filter(p=>(p.date||'').slice(0,7)===month&&(p.date||'')<=today()).reduce((sum,p)=>sum+Number(p.amount||0),0);return `<div class="cards-grid metric-trio"><div class="metric-card"><div class="metric-head">Current card balances <span class="metric-icon">▣</span></div><div class="metric-value">${money(totalCardBalance())}</div><div class="metric-caption">Across ${finance.cards.length} tracked cards</div></div><div class="metric-card"><div class="metric-head">Card purchases this month <span class="metric-icon">↘</span></div><div class="metric-value">${money(cardPurchases.reduce((sum,p)=>sum+Number(p.amount||0),0))}</div><div class="metric-caption">${cardPurchases.length} purchases recorded</div></div><div class="metric-card"><div class="metric-head">Payments this month <span class="metric-icon">↗</span></div><div class="metric-value">${money(payments)}</div><div class="metric-caption">Manually logged payments</div></div></div><div class="panel-heading" style="margin-top:25px"><div><span class="eyebrow">CREDIT CARDS</span><h2>Cards & balances</h2></div><button id="add-card" class="primary">＋ Add card</button></div><p class="debt-note">Start with the card’s current balance. Logging a purchase on a card adds to its balance; recording a payment lowers it. Cash and debit purchases don’t change card balances.</p><div class="subpage-grid">${finance.cards.length?finance.cards.map(c=>`<div class="content-card bank-card"><span class="eyebrow">${escapeHtml(c.issuer||'CREDIT CARD')}</span><h3>${escapeHtml(c.name)}</h3><p>${escapeHtml(c.last4?'•••• '+c.last4:'Tracked manually')}</p><strong>${money(c.balance||0)}</strong><p class="bank-card-caption">Current balance</p><div class="card-actions"><button class="secondary-action" data-card-payment="${escapeHtml(c.id)}">Record payment</button><button class="secondary-action" data-card-adjust="${escapeHtml(c.id)}">Update balance</button></div></div>`).join(''):'<div class="content-card"><h3>Keep every card in view</h3><p>Add cards and log purchases against them. Ledgerly never connects to your bank or card issuer.</p></div>'}</div><h2 class="section-title">Recent card purchases</h2><section class="panel">${purchaseTable([...finance.purchases].filter(p=>p.card).sort((a,b)=>(b.date||'').localeCompare(a.date||'')).slice(0,20))}</section>`}
function subsPage(){const active=finance.subscriptions.filter(s=>s.active!==false),monthly=active.reduce((sum,s)=>sum+Number(s.amount||0)*(s.cadence==='Yearly'?1/12:1),0);return `<div class="cards-grid metric-trio"><div class="metric-card"><div class="metric-head">Monthly run rate <span class="metric-icon">⟳</span></div><div class="metric-value">${money(monthly)}</div><div class="metric-caption">Yearly plans averaged by month</div></div><div class="metric-card"><div class="metric-head">Estimated yearly cost <span class="metric-icon">↗</span></div><div class="metric-value">${money(monthly*12)}</div><div class="metric-caption">If the current subscriptions stay active</div></div><div class="metric-card"><div class="metric-head">Active subscriptions <span class="metric-icon">◎</span></div><div class="metric-value">${active.length}</div><div class="metric-caption">${finance.subscriptions.length-active.length} paused</div></div></div><div class="panel-heading" style="margin-top:25px"><div><span class="eyebrow">RECURRING COSTS</span><h2>Subscriptions</h2></div><button id="add-sub" class="primary">＋ Add subscription</button></div><div class="subpage-grid" style="margin-top:16px">${finance.subscriptions.length?finance.subscriptions.map(s=>`<div class="content-card subscription-card ${s.active===false?'paused':''}"><div class="subscription-status"><span class="status-dot"></span>${s.active===false?'PAUSED':'ACTIVE'} · ${escapeHtml(s.cadence||'MONTHLY')}</div><h3>${escapeHtml(s.name)}</h3><p>${escapeHtml(s.category||'Subscription')}</p><div class="subscription-price">${moneyExact(s.amount)} <span>/ ${escapeHtml((s.cadence||'Monthly').toLowerCase())}</span></div><div class="subscription-actions"><button class="secondary-action" data-sub-toggle="${escapeHtml(s.id)}">${s.active===false?'Resume':'Pause'}</button><button class="secondary-action" data-sub-edit="${escapeHtml(s.id)}">Edit</button><button class="secondary-action danger-action" data-sub-remove="${escapeHtml(s.id)}">Remove</button></div></div>`).join(''):'<div class="content-card"><h3>Know what renews</h3><p>Keep streaming, software, memberships, and other recurring costs in one place.</p></div>'}</div>`}
function subscriptionForm(item=null){const yearly=item?.cadence==='Yearly';const itemId=item?.id;const overlay=document.createElement('div');overlay.className='modal';overlay.innerHTML=`<div class="modal-card"><button class="modal-close" type="button" aria-label="Close">×</button><span class="eyebrow">RECURRING COSTS</span><h2>${item?'Edit':'Add'} a subscription</h2><form><label>Subscription name<input name="name" placeholder="e.g. Music streaming" required value="${escapeHtml(item?.name||'')}"></label><div class="form-row"><label>Amount<input name="amount" type="number" min="0.01" step="0.01" placeholder="0.00" required value="${item?escapeHtml(item.amount):''}"></label><label>Billing frequency<select name="cadence"><option ${yearly?'':'selected'}>Monthly</option><option ${yearly?'selected':''}>Yearly</option></select></label></div><label>Category<input name="category" placeholder="e.g. Entertainment" value="${escapeHtml(item?.category||'')}"></label><p class="form-inline-error" role="alert"></p><button class="primary wide">Save subscription <span>↗</span></button></form></div>`;document.body.appendChild(overlay);overlay.querySelector('.modal-close').onclick=()=>overlay.remove();overlay.onclick=e=>{if(e.target===overlay)overlay.remove()};overlay.querySelector('form').onsubmit=async e=>{e.preventDefault();const previous=JSON.stringify(finance),data=Object.fromEntries(new FormData(e.currentTarget)),button=e.currentTarget.querySelector('.primary');button.disabled=true;const current=itemId?finance.subscriptions.find(s=>s.id===itemId):null;if(current){current.name=data.name.trim();current.amount=Number(data.amount);current.cadence=data.cadence;current.category=data.category.trim()||'Subscription'}else finance.subscriptions.push({id:crypto.randomUUID(),name:data.name.trim(),amount:Number(data.amount),cadence:data.cadence,category:data.category.trim()||'Subscription',active:true});try{await save();overlay.remove();render('Subscriptions')}catch(error){finance=JSON.parse(previous);overlay.querySelector('.form-inline-error').textContent=error.message;button.disabled=false}}}
function goalsPage(){const saved=finance.goals.reduce((sum,g)=>sum+Number(g.saved||0),0),target=finance.goals.reduce((sum,g)=>sum+Number(g.target||0),0),progress=target?Math.min(100,Math.round(saved/target*100)):0;return `<div class="cards-grid metric-trio"><div class="metric-card"><div class="metric-head">Saved toward goals <span class="metric-icon">◎</span></div><div class="metric-value">${money(saved)}</div><div class="metric-caption">Across ${finance.goals.length} goals</div></div><div class="metric-card"><div class="metric-head">Combined progress <span class="metric-icon">↗</span></div><div class="metric-value">${progress}%</div><div class="metric-caption">${money(saved)} saved of ${money(target)}</div></div><div class="metric-card"><div class="metric-head">Still to go <span class="metric-icon">⌁</span></div><div class="metric-value">${money(Math.max(0,target-saved))}</div><div class="metric-caption">Across all current targets</div></div></div><div class="panel-heading" style="margin-top:25px"><div><span class="eyebrow">AIM FOR SOMETHING</span><h2>Goals that feel doable</h2></div><button id="add-goal" class="primary">＋ New goal</button></div><div class="subpage-grid" style="margin-top:16px">${finance.goals.length?finance.goals.map(g=>{let pct=Math.min(100,Math.round(Number(g.saved||0)/Math.max(1,Number(g.target||1))*100));return `<div class="content-card"><span class="eyebrow">${g.date?'TARGET · '+escapeHtml(g.date):'YOUR GOAL'}</span><h3 style="margin-top:10px">${escapeHtml(g.name)}</h3><strong>${money(g.saved)} <span style="color:#929d96;font-size:11px;font-weight:400">of ${money(g.target)}</span></strong><div class="goal-track"><span style="width:${pct}%"></span></div><div class="goal-meta"><span>${pct}% complete</span><button data-add-progress="${escapeHtml(g.id)}" style="border:0;background:none;color:#396d58;font-weight:700">＋ Add progress</button></div></div>`}).join(''):'<div class="content-card"><h3>Pick a goal that matters to you</h3><p>Emergency fund, next trip, paying down a card. Choose a target and celebrate the small steps.</p></div>'}</div>`}
function retirementSchedule(years,annualRate){const points=[totalRetirement()],monthlyRate=Math.pow(1+annualRate/100,1/12)-1;let balance=totalRetirement();for(let month=1;month<=years*12;month++){balance=(balance+monthlyRetirementContributions())*(1+monthlyRate);if(month%12===0)points.push(balance)}return points}
function retirementChart(points){const max=Math.max(1,...points),step=475/Math.max(1,points.length-1),coords=points.map((v,i)=>`${30+i*step},${170-v/max*135}`),poly=coords.join(' '),ys=[35,80,125,170];return `<svg viewBox="0 0 520 190" role="img" aria-label="Projected retirement account balance over time"><defs><linearGradient id="retirement-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#85aa8c" stop-opacity=".28"/><stop offset="1" stop-color="#85aa8c" stop-opacity="0"/></linearGradient></defs>${ys.map(y=>`<line x1="25" y1="${y}" x2="505" y2="${y}" class="chart-grid"/>`).join('')}<polygon points="30,180 ${poly} 505,180" fill="url(#retirement-fill)"/><polyline class="chart-line" points="${poly}"/>${points.map((v,i)=>i===0||i===points.length-1?`<circle class="chart-dot" cx="${30+i*step}" cy="${170-v/max*135}" r="4"/>`: '').join('')}</svg>`}
function retirementPage(){const settings=finance.retirementSettings,years=Number(settings.years),rate=Number(settings.annualRate),points=retirementSchedule(years,rate),future=points[points.length-1],contributions=monthlyRetirementContributions()*years*12;return `<div class="cards-grid metric-trio"><div class="metric-card"><div class="metric-head">Current retirement balance <span class="metric-icon">⌂</span></div><div class="metric-value">${moneyExact(totalRetirement())}</div><div class="metric-caption">Across ${finance.retirement.length} retirement accounts</div></div><div class="metric-card"><div class="metric-head">Monthly contributions <span class="metric-icon">↗</span></div><div class="metric-value">${moneyExact(monthlyRetirementContributions())}</div><div class="metric-caption">Your combined monthly amount</div></div><div class="metric-card"><div class="metric-head">Projected balance <span class="metric-icon">◎</span></div><div class="metric-value" id="projection-value">${moneyExact(future)}</div><div class="metric-caption" id="projection-caption">In ${years} years at ${rate}% estimated annual growth</div></div></div><div class="panel-heading" style="margin-top:25px"><div><span class="eyebrow">401(K), IRA & MORE</span><h2>Retirement accounts</h2></div><button id="add-retirement" class="primary">＋ Add account</button></div><p class="debt-note">Enter balances and total monthly contributions manually; include an employer match in that amount if applicable. Projections are estimates, not guarantees. They assume a steady return compounded monthly and don’t model fees, taxes, inflation, or contribution limits.</p><div class="subpage-grid retirement-accounts">${finance.retirement.length?finance.retirement.map(r=>`<div class="content-card"><span class="debt-type">${escapeHtml(r.type)}</span><h3 style="margin-top:11px">${escapeHtml(r.name)}</h3><div class="metric-value">${moneyExact(r.balance)}</div><p>${moneyExact(r.monthlyContribution)} contributed monthly</p><small class="holding-ticker">Balance as of ${escapeHtml(r.updatedAt||'—')}</small><button class="secondary-action" data-update-retirement="${escapeHtml(r.id)}">Update amounts</button><button class="secondary-action danger-action" data-remove-retirement="${escapeHtml(r.id)}">Remove</button></div>`).join(''):'<div class="content-card"><h3>Start with your current account</h3><p>Add a 401(k), IRA, 403(b), or another retirement account to see a personalized projection.</p></div>'}</div><div class="dashboard-grid retirement-layout"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">ADJUST YOUR ASSUMPTIONS</span><h2>Projection settings</h2></div></div><label class="range-control">Estimated annual return <strong id="rate-label">${rate}%</strong><input id="return-rate" type="range" min="0" max="15" step="0.5" value="${rate}"><small>10% is the starting assumption. Change it to explore scenarios.</small></label><label class="range-control">Time to grow <strong id="years-label">${years} years</strong><input id="retirement-years" type="range" min="1" max="50" step="1" value="${years}"><small>Drag the slider to choose a projection horizon.</small></label><div class="projection-callout"><span>Estimated growth beyond your starting balance and contributions</span><strong id="growth-value">${moneyExact(future-totalRetirement()-contributions)}</strong></div></section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">POSSIBLE FUTURE VALUE</span><h2>Retirement growth projection</h2></div><span class="category-tag">Estimate</span></div><div class="retirement-chart">${retirementChart(points)}</div><div class="chart-labels retirement-chart-labels">${Array.from({length:Math.min(6,years+1)},(_,i)=>`<span>${Math.round(i*years/(Math.min(6,years+1)-1))} yr</span>`).join('')}</div><div class="projection-total"><span>Projected balance</span><strong id="projection-total">${moneyExact(future)}</strong></div></section></div>`}
function updateRetirementProjection(){const rate=Number($('#return-rate').value),years=Number($('#retirement-years').value);finance.retirementSettings={annualRate:rate,years};const points=retirementSchedule(years,rate),future=points[points.length-1],contributions=monthlyRetirementContributions()*years*12;$('#rate-label').textContent=`${rate}%`;$('#years-label').textContent=`${years} years`;$('#projection-value').textContent=moneyExact(future);$('#projection-total').textContent=moneyExact(future);$('#projection-caption').textContent=`In ${years} years at ${rate}% estimated annual growth`;$('#growth-value').textContent=moneyExact(future-totalRetirement()-contributions);$('.retirement-chart').innerHTML=retirementChart(points);$('.retirement-chart-labels').innerHTML=Array.from({length:Math.min(6,years+1)},(_,i)=>`<span>${Math.round(i*years/(Math.min(6,years+1)-1))} yr</span>`).join('');clearTimeout(retirementSaveTimer);retirementSaveTimer=setTimeout(()=>save().catch(()=>{}),300)}
function retirementForm(){const overlay=document.createElement('div');overlay.className='modal';overlay.innerHTML=`<div class="modal-card"><button class="modal-close" type="button">×</button><span class="eyebrow">RETIREMENT SAVINGS</span><h2>Add a retirement account</h2><form><label>Account name<input name="name" placeholder="e.g. Workplace 401(k)" required></label><label>Account type<select name="type"><option>401(k)</option><option>Roth IRA</option><option>Traditional IRA</option><option>403(b)</option><option>Pension</option><option>Other</option></select></label><div class="form-row"><label>Current balance<input name="balance" type="number" min="0" step="0.01" placeholder="0.00" required></label><label>Monthly contribution (including any match)<input name="contribution" type="number" min="0" step="0.01" placeholder="0.00" value="0" required></label></div><button class="primary wide">Save account <span>↗</span></button></form></div>`;document.body.appendChild(overlay);overlay.querySelector('.modal-close').onclick=()=>overlay.remove();overlay.onclick=e=>{if(e.target===overlay)overlay.remove()};overlay.querySelector('form').onsubmit=async e=>{e.preventDefault();const data=new FormData(e.target);finance.retirement.push({id:crypto.randomUUID(),name:data.get('name').trim(),type:data.get('type'),balance:Number(data.get('balance')),monthlyContribution:Number(data.get('contribution')),updatedAt:today()});try{await save();overlay.remove();render('Retirement')}catch(error){alert(error.message)}}}
function debtsPage(){const paydown=debtPaydownSinceTracking();return `<div class="cards-grid metric-trio"><div class="metric-card"><div class="metric-head">Total loan balances <span class="metric-icon">↘</span></div><div class="metric-value">${money(totalDebt())}</div><div class="metric-caption">Across ${finance.debts.length} loans and debts</div></div><div class="metric-card"><div class="metric-head">Expected monthly payments <span class="metric-icon">↻</span></div><div class="metric-value">${money(monthlyDebtPayments())}</div><div class="metric-caption">Based on amounts you entered</div></div><div class="metric-card"><div class="metric-head">Paid down since tracking <span class="metric-icon">↗</span></div><div class="metric-value ${paydown===null?'':paydown>=0?'profit-up':'profit-down'}">${paydown===null?'—':`${paydown>=0?'+':''}${money(paydown)}`}</div><div class="metric-caption">${paydown===null?'Add another monthly balance update to compare':'Across loans with multiple snapshots'}</div></div></div><div class="panel-heading" style="margin-top:25px"><div><span class="eyebrow">LOANS & OTHER DEBTS</span><h2>Your debt overview</h2></div><button id="add-debt" class="primary">＋ Add debt</button></div><p class="debt-note">Enter the current amount owed and your usual monthly payment. Update the balance when you check your lender statement; Ledgerly doesn’t estimate interest or connect to lenders. If you track a card in Cards, don’t add it again here.</p><div class="subpage-grid">${finance.debts.length?finance.debts.map(d=>`<div class="content-card"><span class="debt-type">${escapeHtml(d.type||'Other debt')}</span><h3 style="margin-top:12px">${escapeHtml(d.name)}</h3><div class="metric-value">${money(d.balance)}</div><p>As of ${escapeHtml(d.updatedAt||today())}</p><p>${d.apr?`${escapeHtml(d.apr)}% APR · `:''}${money(d.payment)} monthly payment</p><button class="secondary-action" data-debt-update="${escapeHtml(d.id)}">Update balance</button></div>`).join(''):'<div class="content-card"><h3>See the whole picture</h3><p>Add a credit card balance, student loan, car loan, mortgage, or another debt. Update each balance over time to track progress.</p></div>'}</div>`}
function adminPage(){return `<section class="panel"><div class="panel-heading"><div><span class="eyebrow">RESTRICTED ACCESS</span><h2>Registered users</h2></div><span class="metric-caption">Login activity is recorded from now on.</span></div><p class="debt-note">Removing a user permanently deletes their account, encrypted finance data, and login history, and ends their active sessions.</p><div id="admin-users"><div class="empty">Loading users…</div></div></section>`}
function securityPage(){return `<section class="panel recovery-panel"><span class="eyebrow">ACCOUNT SECURITY</span><h2>Keep a way back into your account</h2><p>Your recovery code can reset your password and unlock your encrypted finance data. Store it somewhere private, such as a password manager or a printed copy kept in a safe place.</p><p class="debt-note">Rotating the code immediately invalidates your old one. Save the new code before leaving this page. Ledgerly will never show the full code again.</p><button class="primary" data-rotate-recovery>Generate a new recovery code <span>↗</span></button></section>`}
function showRecoveryCode(code,title){return new Promise(resolve=>{const overlay=document.createElement('div');overlay.className='modal recovery-modal';overlay.innerHTML=`<div class="modal-card"><span class="eyebrow">ACCOUNT RECOVERY</span><h2>${escapeHtml(title)}</h2><p>This code can reset your password and recover access to your encrypted finance data. It will only be shown once. Save it in a password manager or print it and keep it somewhere private.</p><label>Recovery code<textarea class="recovery-code" readonly rows="3" spellcheck="false"></textarea></label><button type="button" class="secondary-action recovery-copy">Copy code</button><label class="recovery-confirm"><input type="checkbox"> I’ve saved this code somewhere safe</label><button type="button" class="primary wide recovery-continue" disabled>Continue</button></div>`;document.body.appendChild(overlay);const field=overlay.querySelector('.recovery-code');field.value=code;const checkbox=overlay.querySelector('.recovery-confirm input');const proceed=overlay.querySelector('.recovery-continue');checkbox.onchange=()=>{proceed.disabled=!checkbox.checked};overlay.querySelector('.recovery-copy').onclick=async()=>{try{await navigator.clipboard.writeText(code);overlay.querySelector('.recovery-copy').textContent='Copied'}catch{field.select();document.execCommand('copy');overlay.querySelector('.recovery-copy').textContent='Select and copy the code'}};proceed.onclick=()=>{overlay.remove();resolve()}})}
function recoveryForm(){const overlay=document.createElement('div');overlay.className='modal recovery-modal';overlay.innerHTML=`<div class="modal-card"><button class="modal-close" type="button">×</button><span class="eyebrow">ACCOUNT RECOVERY</span><h2>Reset your password</h2><p>Enter your email and recovery code. Your old recovery code will be replaced after a successful reset.</p><form><label>Email address<input name="email" type="email" autocomplete="email" required value="${escapeHtml($('#email').value)}"></label><label>Recovery code<input name="recovery_code" autocomplete="off" required></label><label>New password<input name="new_password" type="password" minlength="12" autocomplete="new-password" required></label><p class="auth-error recovery-error"></p><button class="primary wide">Reset password <span>↗</span></button></form></div>`;document.body.appendChild(overlay);overlay.querySelector('.modal-close').onclick=()=>overlay.remove();overlay.onclick=e=>{if(e.target===overlay)overlay.remove()};overlay.querySelector('form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('.primary');button.disabled=true;const data=Object.fromEntries(new FormData(form));try{const result=await api('/api/recover-password',data);$('#email').value=data.email;$('#password').value='';overlay.remove();await showRecoveryCode(result.recovery_code,'Password reset — save your new recovery code');if(registerMode)setMode();$('#auth-error').textContent='Password updated. Sign in with your new password.'}catch(error){form.querySelector('.recovery-error').textContent=error.message;button.disabled=false}}}
async function loadAdminUsers(){const root=$('#admin-users');if(!root)return;try{const users=await api('/api/admin/users');root.innerHTML=users.length?`<table class="table admin-table"><thead><tr><th>EMAIL</th><th>LAST LOGIN</th><th>LOGINS · 30 DAYS</th><th></th></tr></thead><tbody>${users.map(u=>`<tr><td>${escapeHtml(u.email)}${u.email.toLowerCase()===email.toLowerCase()?' <span class="category-tag">You</span>':''}</td><td>${u.last_login?escapeHtml(new Date(u.last_login).toLocaleString()):'Not recorded yet'}</td><td>${Number(u.logins_30d)}</td><td class="amount">${u.email.toLowerCase()===email.toLowerCase()?'Current admin':`<button class="secondary-action danger-action" data-delete-user="${u.id}" data-user-email="${escapeHtml(u.email)}">Remove user</button>`}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No registered users found.</div>';$$('[data-delete-user]').forEach(button=>button.onclick=async()=>{const userEmail=button.dataset.userEmail;if(!confirm(`Permanently remove ${userEmail}, their encrypted finance data, and login history? This cannot be undone.`))return;button.disabled=true;try{const response=await fetch(`/api/admin/users/${button.dataset.deleteUser}`,{method:'DELETE',credentials:'same-origin'});if(!response.ok)throw new Error(response.status===403?'Admin access required.':'Could not remove this user.');await loadAdminUsers()}catch(error){alert(error.message);button.disabled=false}})}catch(error){root.innerHTML=`<div class="empty">${escapeHtml(error.message||'Could not load users.')}</div>`}}
function bindPage(){
  $$('[data-goto]').forEach(b=>b.onclick=()=>render(b.dataset.goto));
  if($('#admin-users'))loadAdminUsers();
  $$('[data-rotate-recovery]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{const result=await api('/api/recovery/rotate',{});await showRecoveryCode(result.recovery_code,'Save your new recovery code')}catch(error){alert(error.message)}finally{button.disabled=false}});
  if($('#chart-range'))$('#chart-range').onchange=e=>{const n=Number(e.target.value);$('.chart-wrap').innerHTML=chart(n);$('.chart-labels').innerHTML=monthLabels(n)};
  if($('#search')){const update=()=>{const q=$('#search').value.toLowerCase(),c=$('#filter-category').value,m=$('#filter-month').value;$('#purchase-results').innerHTML=purchaseTable([...finance.purchases].filter(p=>(!q||p.merchant.toLowerCase().includes(q))&&(!c||p.category===c)&&(!m||(p.date||'').startsWith(m))).sort((a,b)=>b.date.localeCompare(a.date)))};$('#search').oninput=update;$('#filter-category').onchange=update;$('#filter-month').onchange=update}
  if($('#add-account'))$('#add-account').onclick=()=>quickForm('Monthly account snapshot','Account name,Current balance,Snapshot date',async([name,amount,date])=>{const d=date||today(),month=d.slice(0,7),existing=finance.accounts.find(a=>a.name.trim().toLowerCase()===name.trim().toLowerCase()&&(a.date||'').slice(0,7)===month);if(existing){existing.amount=Number(amount);existing.date=d}else finance.accounts.push({name:name.trim(),amount:Number(amount),date:d});await save();render('Accounts')});
  if($('#add-card'))$('#add-card').onclick=()=>quickForm('Add a card','Card name,Current balance,Issuer',async([name,balance,issuer])=>{finance.cards.push({id:crypto.randomUUID(),name,issuer,balance:Number(balance)||0});await save();render('Cards')});
  if($('#add-investment'))$('#add-investment').onclick=investmentForm;
  $$('[data-update-investment]').forEach(b=>b.onclick=()=>{const holding=finance.investments.find(i=>i.id===b.dataset.updateInvestment);if(!holding)return;quickForm('Update holding','As of date,Number of shares or units,Cost basis per share/unit,Current price per share/unit',async([date,units,costBasis,price])=>{holding.units=Number(units);if(costBasis!=='')holding.costBasis=Number(costBasis);if(price!=='')holding.price=Number(price);holding.updatedAt=date||today();await save();render('Investments')},{'As of date':today(),'Number of shares or units':holding.units,'Cost basis per share/unit':holding.costBasis??'','Current price per share/unit':holding.price})});
  if($('#add-retirement'))$('#add-retirement').onclick=retirementForm;
  $$('[data-update-retirement]').forEach(b=>b.onclick=()=>quickForm('Update retirement amounts','Current balance,Monthly contribution',async([balance,contribution])=>{const account=finance.retirement.find(r=>r.id===b.dataset.updateRetirement);if(account){account.balance=Number(balance);account.monthlyContribution=Number(contribution);account.updatedAt=today()}await save();render('Retirement')}));
  $$('[data-remove-retirement]').forEach(b=>b.onclick=async()=>{const account=finance.retirement.find(r=>r.id===b.dataset.removeRetirement);if(!account||!confirm(`Remove ${account.name} from retirement tracking?`))return;finance.retirement=finance.retirement.filter(r=>r.id!==account.id);await save();render('Retirement')});
  if($('#return-rate')){const update=()=>updateRetirementProjection();$('#return-rate').oninput=update;$('#retirement-years').oninput=update}
  $$('[data-card-payment]').forEach(b=>b.onclick=()=>quickForm('Record a card payment','Payment date,Payment amount',async([date,amount])=>{const card=finance.cards.find(c=>c.id===b.dataset.cardPayment);if(!card)return;const value=Number(amount);card.balance=Math.max(0,Number(card.balance||0)-value);finance.cardPayments.push({card:card.name,amount:value,date:date||today()});await save();render('Cards')}));
  $$('[data-card-adjust]').forEach(b=>b.onclick=()=>quickForm('Update card balance','As of date,Current balance',async([date,balance])=>{const c=finance.cards.find(x=>x.id===b.dataset.cardAdjust);if(c){c.balance=Number(balance);c.updatedAt=date||today()}await save();render('Cards')}));
  if($('#add-debt'))$('#add-debt').onclick=()=>quickForm('Add a loan or debt','Name,Current balance,Debt type (e.g. student loan),APR %,Monthly payment',async([name,balance,type,apr,payment])=>{finance.debts.push({id:crypto.randomUUID(),name,type:type||'Other debt',balance:Number(balance)||0,apr:Number(apr)||0,payment:Number(payment)||0,updatedAt:today(),history:[{date:today(),balance:Number(balance)||0}]});await save();render('Debts')});
  $$('[data-debt-update]').forEach(b=>b.onclick=()=>quickForm('Update debt balance','Snapshot date,Current balance',async([date,balance])=>{const d=finance.debts.find(x=>x.id===b.dataset.debtUpdate);if(!d)return;const snapDate=date||today(),month=snapDate.slice(0,7);d.balance=Number(balance);d.updatedAt=snapDate;d.history??=[];const existing=d.history.find(h=>(h.date||'').slice(0,7)===month);if(existing){existing.balance=d.balance;existing.date=snapDate}else d.history.push({date:snapDate,balance:d.balance});await save();render('Debts')}));
  if($('#add-sub'))$('#add-sub').onclick=subscriptionForm;
  $$('[data-sub-edit]').forEach(button=>button.onclick=()=>{const item=finance.subscriptions.find(s=>s.id===button.dataset.subEdit);if(item)subscriptionForm(item)});
  $$('[data-sub-toggle]').forEach(button=>button.onclick=async()=>{const previous=JSON.stringify(finance),item=finance.subscriptions.find(s=>s.id===button.dataset.subToggle);if(!item)return;item.active=item.active===false;try{await save();render('Subscriptions')}catch(error){finance=JSON.parse(previous);alert(error.message)}});
  $$('[data-sub-remove]').forEach(button=>button.onclick=async()=>{const item=finance.subscriptions.find(s=>s.id===button.dataset.subRemove);if(!item||!confirm(`Remove ${item.name} from subscription tracking?`))return;const previous=JSON.stringify(finance);finance.subscriptions=finance.subscriptions.filter(s=>s.id!==item.id);try{await save();render('Subscriptions')}catch(error){finance=JSON.parse(previous);alert(error.message)}});
  if($('#add-goal'))$('#add-goal').onclick=()=>quickForm('Create a goal','Goal name,Target amount,Target date (optional)',async([name,target,date])=>{finance.goals.push({id:crypto.randomUUID(),name,target:Number(target),saved:0,date});await save();render('Goals')});
  $$('[data-add-progress]').forEach(b=>b.onclick=()=>{const amount=Number(prompt('How much progress would you like to add?'));if(amount>0){const g=finance.goals.find(x=>x.id===b.dataset.addProgress);g.saved=Number(g.saved||0)+amount;save().then(()=>render('Goals'))}});
}
function investmentForm(){
  const overlay=document.createElement('div');overlay.className='modal';
  overlay.innerHTML=`<div class="modal-card"><button class="modal-close" type="button">×</button><span class="eyebrow">MANUAL PORTFOLIO</span><h2>Add an investment</h2><form id="holding-form"><label>Asset name<input name="name" placeholder="e.g. Apple Inc. or 1-year CD" required></label><div class="form-row"><label>Category<select name="category"><option>Stocks</option><option>ETFs & funds</option><option>Crypto</option><option>CDs</option><option>Bonds</option><option>Other</option></select></label><label>Ticker (optional)<input name="ticker" placeholder="e.g. AAPL"></label></div><div class="form-row"><label>Shares or units<input name="units" type="number" min="0.000001" step="0.000001" value="1" required></label><label>Current price per share/unit<input name="price" type="number" min="0" step="any" placeholder="0.00" required></label></div><label>Cost basis per share/unit (optional)<input name="costBasis" type="number" min="0" step="any" placeholder="Enter this to track P/L"></label><p class="debt-note">For a CD, use 1 unit and enter the CD’s current value as the price. Add your average purchase price as cost basis to track profit or loss.</p><button class="primary wide">Save holding <span>↗</span></button></form></div>`;
  document.body.appendChild(overlay);overlay.querySelector('.modal-close').onclick=()=>overlay.remove();overlay.onclick=e=>{if(e.target===overlay)overlay.remove()};
  overlay.querySelector('form').onsubmit=async e=>{e.preventDefault();const previous=JSON.stringify(finance),form=new FormData(e.target),basis=form.get('costBasis');finance.investments.push({id:crypto.randomUUID(),name:form.get('name').trim(),ticker:form.get('ticker').trim().toUpperCase(),category:form.get('category'),units:Number(form.get('units')),price:Number(form.get('price')),costBasis:basis===''?null:Number(basis),updatedAt:today()});try{await save();overlay.remove();render('Investments')}catch(error){finance=JSON.parse(previous);alert(error.message)}}
}
function quickForm(title,fields,done,initialValues={}){const vals=fields.split(',');let form=document.createElement('div');form.className='modal';form.innerHTML=`<div class="modal-card"><button class="modal-close" type="button" aria-label="Close">×</button><span class="eyebrow">LEDGERLY</span><h2>${title}</h2><form>${vals.map((v,i)=>`<label>${v}<input ${/date/i.test(v)?'type="date"':/balance|amount|apr|payment|target|shares|units|price/i.test(v)?'type="number" step="any" min="0"':''} placeholder="${v}" value="${escapeHtml(initialValues[v]??'')}" ${i<2&&!/date/i.test(v)?'required':''}></label>`).join('')}<p class="form-inline-error" role="alert"></p><button class="primary wide">Save</button></form></div>`;document.body.appendChild(form);form.querySelector('.modal-close').onclick=()=>form.remove();form.onclick=e=>{if(e.target===form)form.remove()};form.querySelector('form').onsubmit=async e=>{e.preventDefault();const values=[...form.querySelectorAll('input')].map(i=>i.value),button=form.querySelector('.primary'),previous=JSON.stringify(finance);button.disabled=true;try{await done(values);form.remove()}catch(error){finance=JSON.parse(previous);form.querySelector('.form-inline-error').textContent=error.message||'Could not save. Please try again.';button.disabled=false}}}
$('#add-transaction').onclick=()=>{$('#modal').classList.remove('hidden');$('#purchase-form').date.value=today();$('#card-select').innerHTML='<option value="">Debit / cash</option>'+finance.cards.map(c=>`<option>${escapeHtml(c.name)}</option>`).join('')};$('#close-modal').onclick=()=>$('#modal').classList.add('hidden');$('#modal').onclick=e=>{if(e.target.id==='modal')$('#modal').classList.add('hidden')};$('#purchase-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const purchase={merchant:f.get('merchant'),amount:Number(f.get('amount')),date:f.get('date'),category:f.get('category'),card:f.get('card')};finance.purchases.push(purchase);const chargedCard=finance.cards.find(c=>c.name===purchase.card);if(chargedCard)chargedCard.balance=Number(chargedCard.balance||0)+purchase.amount;try{await save();$('#modal').classList.add('hidden');e.target.reset();render($('#page-title').textContent)}catch(err){alert(err.message)}};
api('/api/finance').then(loadApp).catch(()=>{});














